import { DomainError } from '../errors/DomainError';
import { LoanPeriod } from '../value-objects/LoanPeriod';

const DAY_MS = 24 * 60 * 60 * 1000;

export class Loan {
  private returnedAt: Date | undefined;

  private constructor(
    readonly id: string,
    readonly bookId: string,
    readonly memberId: string,
    readonly borrowedAt: Date,
    readonly dueAt: Date,
  ) {}

  static open(id: string, bookId: string, memberId: string, borrowedAt: Date, period: LoanPeriod): Loan {
    return new Loan(id, bookId, memberId, borrowedAt, period.dueDateFrom(borrowedAt));
  }

  get isActive(): boolean {
    return this.returnedAt === undefined;
  }

  close(at: Date): void {
    if (!this.isActive) throw new DomainError('LOAN_CLOSED', `Loan ${this.id} is already returned`);
    this.returnedAt = at;
  }

  isOverdue(now: Date): boolean {
    return this.isActive && now.getTime() > this.dueAt.getTime();
  }

  daysOverdue(now: Date): number {
    if (!this.isOverdue(now)) return 0;
    return Math.ceil((now.getTime() - this.dueAt.getTime()) / DAY_MS);
  }
}

import { DomainError } from '../errors/DomainError';

export class Member {
  constructor(
    readonly id: string,
    readonly name: string,
    readonly email: string,
    readonly maxActiveLoans: number,
  ) {
    if (!email.includes('@')) throw new DomainError('INVALID_MEMBER', `Invalid e-mail: ${email}`);
    if (maxActiveLoans < 1) throw new DomainError('INVALID_MEMBER', 'A member may borrow at least one book');
  }
}

export class DomainError extends Error {
  constructor(readonly code: string, message: string) {
    super(message);
    this.name = 'DomainError';
  }
}

import { Book } from '../entities/Book';

export interface BookRepository {
  findById(id: string): Promise<Book | undefined>;
  save(book: Book): Promise<void>;
}

import { Loan } from '../entities/Loan';

export interface LoanRepository {
  findById(id: string): Promise<Loan | undefined>;
  findActiveByMember(memberId: string): Promise<Loan[]>;
  findActive(): Promise<Loan[]>;
  save(loan: Loan): Promise<void>;
}

import { Member } from '../entities/Member';

export interface MemberRepository {
  findById(id: string): Promise<Member | undefined>;
  save(member: Member): Promise<void>;
}

import { Loan } from '../entities/Loan';

export class FineCalculator {
  constructor(private readonly centsPerDay: number) {}

  fineInCents(loan: Loan, now: Date): number {
    return loan.daysOverdue(now) * this.centsPerDay;
  }
}

