    try {
      return ok(await this.returnBook.execute(String(request.params['loanId'])));
    } catch (error) {
      return toErrorResponse(error);
    }
  }

  async overdue(): Promise<HttpResponse> {
    return ok(await this.listOverdue.execute());
  }
}

