import { Loan } from '../../domain/entities/Loan';
import { HttpResponse, ok } from '../../infrastructure/http/HttpTypes';

export interface LoanDto {
  id: string;
  bookId: string;
  memberId: string;
  dueAt: string;
  overdue: boolean;
}

export function toLoanResponse(loan: Loan, now: Date): HttpResponse {
  return ok(toLoanDto(loan, now));
}

export function toLoanDto(loan: Loan, now: Date): LoanDto {
  return {
    id: loan.id,
    bookId: loan.bookId,
    memberId: loan.memberId,
    dueAt: loan.dueAt.toISOString(),
    overdue: loan.isOverdue(now),
  };
}

export interface HttpRequest {
  params: Record<string, string>;
  body: Record<string, unknown>;
}

export interface HttpResponse {
  status: number;
  body: unknown;
}

export function ok(body: unknown): HttpResponse {
  return { status: 200, body };
}

export function created(body: unknown): HttpResponse {
  return { status: 201, body };
}

export function fail(status: number, message: string): HttpResponse {
  return { status, body: { error: message } };
}

