/** Reporting reads the order table directly (one layer down): no gateway exists for an ad-hoc aggregate. */
export class SalesReportService {
  constructor(private readonly db: InMemoryDatabase) {}

  revenue(): Money {
    let cents = 0;
    for (const order of this.db.table<OrderRecord>('orders').values()) {
      if (order.status !== 'placed') continue;
      cents += order.lines.reduce((sum, line) => sum + line.quantity * line.unitPriceCents, 0) - order.discountCents;
    }
    return Money.ofCents(Math.max(0, cents));
  }
}

