  constructor(
    readonly id: string,
    readonly name: string,
    readonly email: string,
    readonly loyaltyTier: 'standard' | 'gold',
  ) {}

  openOrders(orders: readonly Order[]): Order[] {
    return orders.filter((order) => order.isPlacedBy(this) && order.status === 'placed');
  }

  get isGold(): boolean {
    return this.loyaltyTier === 'gold';
  }
}

