import { ArgumentsHost, Catch, ExceptionFilter, HttpStatus } from '@nestjs/common';
import { DomainError, DomainErrorKind } from '../../domain/domain-error';

const STATUS: Record<DomainErrorKind, HttpStatus> = {
  'not-found': HttpStatus.NOT_FOUND,
  conflict: HttpStatus.CONFLICT,
  invalid: HttpStatus.BAD_REQUEST,
};

interface JsonResponse {
  status(code: number): { json(body: unknown): void };
}

/** Exception filter (NestJS docs, "Exception filters"): maps domain errors to HTTP status codes. */
@Catch(DomainError)
export class DomainErrorFilter implements ExceptionFilter<DomainError> {
  catch(exception: DomainError, host: ArgumentsHost): void {
    host.switchToHttp().getResponse<JsonResponse>().status(STATUS[exception.kind]).json({ message: exception.message });
  }
}

import { CanActivate, ExecutionContext, Injectable } from '@nestjs/common';

export const API_KEY_HEADER = 'x-api-key';

@Injectable()
export class ApiKeyGuard implements CanActivate {
  canActivate(context: ExecutionContext): boolean {
    const request = context.switchToHttp().getRequest<{ headers: Record<string, string | undefined> }>();
    return (request.headers[API_KEY_HEADER] ?? '').length > 0;
  }
}

import { Attendee } from './attendee';

export const ATTENDEE_REPOSITORY = 'ATTENDEE_REPOSITORY';

export interface AttendeeRepository {
  findById(id: string): Promise<Attendee | undefined>;
  save(attendee: Attendee): Promise<void>;
}

import { DomainError } from './domain-error';

export class Attendee {
  constructor(
    readonly id: string,
    readonly name: string,
    readonly email: string,
  ) {
    if (!email.includes('@')) throw new DomainError('invalid', `Invalid e-mail: ${email}`);
  }
}

export type DomainErrorKind = 'not-found' | 'conflict' | 'invalid';

export class DomainError extends Error {
  constructor(readonly kind: DomainErrorKind, message: string) {
    super(message);
    this.name = 'DomainError';
  }
}

