import { Injectable } from '@nestjs/common';
import { Workshop } from '../domain/workshop';
import { WorkshopRepository } from '../domain/workshop-repository';
import { WorkshopResponseDto } from './dto/workshop-response.dto';

@Injectable()
export class InMemoryWorkshopRepository implements WorkshopRepository {
  private readonly rows = new Map<string, Workshop>();

  async findById(id: string): Promise<Workshop | undefined> {
    return this.rows.get(id);
  }

  async findAll(): Promise<Workshop[]> {
    return [...this.rows.values()];
  }

  async findAllAsResponse(): Promise<WorkshopResponseDto[]> {
    return [...this.rows.values()].map((w) => WorkshopResponseDto.from(w));
  }

  async save(workshop: Workshop): Promise<void> {
    this.rows.set(workshop.id, workshop);
  }
}

import { Workshop } from '../../domain/workshop';

export class WorkshopResponseDto {
  id!: string;
  title!: string;
  seatsLeft!: number;
  startsAt!: string;

  static from(workshop: Workshop): WorkshopResponseDto {
    return Object.assign(new WorkshopResponseDto(), {
      id: workshop.id,
      title: workshop.title,
      seatsLeft: workshop.seatsLeft,
      startsAt: workshop.startsAt.toISOString(),
    });
  }
}

