import { Registration } from '../../domain/registration';
import { WorkshopResponseDto } from '../../workshops/dto/workshop-response.dto';

export class RegistrationResponseDto {
  id!: string;
  workshopId!: string;
  attendeeId!: string;
  active!: boolean;
  workshop?: WorkshopResponseDto;

  static from(registration: Registration): RegistrationResponseDto {
    return Object.assign(new RegistrationResponseDto(), {
      id: registration.id,
      workshopId: registration.workshopId,
      attendeeId: registration.attendeeId,
      active: registration.isActive,
    });
  }
}

import { Workshop } from '../../domain/workshop';
import { RegistrationResponseDto } from '../../registrations/dto/registration-response.dto';

export class WorkshopResponseDto {
  id!: string;
  title!: string;
  seatsLeft!: number;
  startsAt!: string;
  registrations?: RegistrationResponseDto[];

  static from(workshop: Workshop): WorkshopResponseDto {
    return Object.assign(new WorkshopResponseDto(), {
      id: workshop.id,
      title: workshop.title,
      seatsLeft: workshop.seatsLeft,
      startsAt: workshop.startsAt.toISOString(),
    });
  }
}

