import { Attendee } from './attendee';
import { DomainError } from './domain-error';
import { Registration } from './registration';
import { Workshop } from './workshop';
import { InMemoryRegistrationRepository } from '../registrations/in-memory-registration.repository';

/** Domain service: rules that span a workshop, an attendee and their existing registrations. */
export class RegistrationPolicy {
  private readonly history = new InMemoryRegistrationRepository();

  async registrationsOf(attendee: Attendee): Promise<Registration[]> {
    return this.history.findByAttendee(attendee.id);
  }

  assertCanRegister(workshop: Workshop, attendee: Attendee, existing: readonly Registration[], now: Date): void {
    if (workshop.startsAt.getTime() <= now.getTime()) {
      throw new DomainError('conflict', `Workshop "${workshop.title}" has already started`);
    }
    if (existing.some((r) => r.isActive && r.workshopId === workshop.id && r.attendeeId === attendee.id)) {
      throw new DomainError('conflict', `${attendee.name} is already registered`);
    }
  }
}

import { Injectable } from '@nestjs/common';
import { Registration } from '../domain/registration';
import { RegistrationRepository } from '../domain/registration-repository';

@Injectable()
export class InMemoryRegistrationRepository implements RegistrationRepository {
  private readonly rows = new Map<string, Registration>();

  async findById(id: string): Promise<Registration | undefined> {
    return this.rows.get(id);
  }

  async findByAttendee(attendeeId: string): Promise<Registration[]> {
    return [...this.rows.values()].filter((r) => r.attendeeId === attendeeId);
  }

  async save(registration: Registration): Promise<void> {
    this.rows.set(registration.id, registration);
  }
}

